package com.moviebooking.notification.service.impl;
import com.moviebooking.notification.entity.Notification;import com.moviebooking.notification.exception.EmailDeliveryException;import com.moviebooking.notification.service.EmailService;import jakarta.mail.internet.MimeMessage;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.javamail.*;import org.springframework.stereotype.Service;
@Service @Slf4j @RequiredArgsConstructor public class SmtpEmailService implements EmailService {private final JavaMailSender mailSender;@Value("${notification.mail.enabled:false}") private boolean enabled;@Value("${notification.mail.from:no-reply@moviebooking.local}") private String from;public void send(Notification n){if(!enabled){log.info("Development email notification: recipient={} subject={} notificationId={}",n.getRecipient(),n.getSubject(),n.getId());return;}try{MimeMessage m=mailSender.createMimeMessage();MimeMessageHelper h=new MimeMessageHelper(m,true,"UTF-8");h.setFrom(from);h.setTo(n.getRecipient());h.setSubject(n.getSubject());h.setText(n.getMessage(),true);mailSender.send(m);}catch(Exception e){throw new EmailDeliveryException("Email delivery failed",e);}}}
